                 1.387741800000000e-08 * T2 + 9.886060000000000e-12 * T3;
    // species 8: N2
    species[8] = +1.408240000000000e-03 - 7.926444000000000e-06 * T +
                 1.692454500000000e-08 * T2 - 9.779420000000000e-12 * T3;
    // species 11: CO
