    dqdci = (3.8 - 1) * dcdc_fac;
    J[168] -= dqdci; // dwdot[H]/d[CO2]
    J[173] -= dqdci; // dwdot[O2]/d[CO2]
    J[174] += dqdci; // dwdot[HO2]/d[CO2]
