  J[182] -= dqdT; // dwdot[H]/dT
  J[187] -= dqdT; // dwdot[O2]/dT
  J[188] += dqdT; // dwdot[HO2]/dT

  // reaction 21: H2O2 (+M) <=> 2 OH (+M)
  // a third-body and pressure-fall-off reaction
  // 3-body correction factor
  alpha = mixture + (3.7 - 1) * sc[1] + (7.5 - 1) * sc[4] + (1.2 - 1) * sc[5] +
          (7.7 - 1) * sc[7] + (1.5 - 1) * sc[8] + (0.65 - 1) * sc[10] +
          (2.8 - 1) * sc[11] + (1.6 - 1) * sc[12];
  // forward
  phi_f = sc[7];
  k_f = 2000000000000 * exp(0.9 * logT - (24531.3092413143) * invT);
  dlnkfdT = 0.9 * invT + (24531.3092413143) * invT2;
  // pressure-fall-off
