            dlogFdlogPr * dlogPrdT;
  // reverse
  phi_r = (sc[3] * sc[3]);
  Kc = refC * (kc_fast ? (ge[3] * ge[3] * inv_ge[7])
                       : exp(-2.000000 * g_RT[3] + g_RT[7]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[7]) + (2.000000 * h_RT[3]) - 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
