  J[127] -= dqdci;     // dwdot[H2]/d[AR]
  // d()/dT
  J[182] += 2 * dqdT; // dwdot[H]/dT
  J[183] -= dqdT;     // dwdot[H2]/dT

  // reaction 7: H2 + HE <=> 2 H + HE
