  wdot[0] += 2 * q; // H
  wdot[1] -= q;     // H2
  // d()/d[H]
  dqdci = -k_r * 2.000000 * sc[0] * sc[10];
  J[0] += 2 * dqdci; // dwdot[H]/d[H]
  J[1] -= dqdci;     // dwdot[H2]/d[H]
