  J[184] += -2 * dqdT; // dwdot[O]/dT
  J[187] += dqdT;      // dwdot[O2]/dT

  // reaction 9: 2 O + AR <=> O2 + AR
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = (sc[2] * sc[2]) * sc[9];
  k_f = 18.86 * exp(-(-899.751398458839) * invT);
  dlnkfdT = (-899.751398458839) * invT2;
  // reverse
  phi_r = sc[5] * sc[9];
  Kc = refCinv * (kc_fast ? (ge[5] * inv_ge[2] * inv_ge[2])
                          : exp(2.000000 * g_RT[2] - g_RT[5]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(2.000000 * h_RT[2] + h_RT[9]) + (h_RT[5] + h_RT[9]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[2] -= 2 * q; // O
  wdot[5] += q;     // O2
  // d()/d[O]
  dqdci = +k_f * 2.000000 * sc[2] * sc[9];
  J[30] += -2 * dqdci; // dwdot[O]/d[O]
  J[33] += dqdci;      // dwdot[O2]/d[O]
  // d()/d[O2]
  dqdci = -k_r * sc[9];
  J[72] += -2 * dqdci; // dwdot[O]/d[O2]
  J[75] += dqdci;      // dwdot[O2]/d[O2]
  // d()/d[AR]
  dqdci = +k_f * sc[2] * sc[2] - k_r * sc[5];
  J[128] += -2 * dqdci; // dwdot[O]/d[AR]
  J[131] += dqdci;      // dwdot[O2]/d[AR]
  // d()/dT
  J[184] += -2 * dqdT; // dwdot[O]/dT
  J[187] += dqdT;      // dwdot[O2]/dT

  // reaction 10: 2 O + HE <=> O2 + HE
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = (sc[2] * sc[2]) * sc[10];
  k_f = 18.86 * exp(-(-899.751398458839) * invT);
  dlnkfdT = (-899.751398458839) * invT2;
  // reverse
  phi_r = sc[5] * sc[10];
  Kc = refCinv * (kc_fast ? (ge[5] * inv_ge[2] * inv_ge[2])
                          : exp(2.000000 * g_RT[2] - g_RT[5]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(2.000000 * h_RT[2] + h_RT[10]) + (h_RT[5] + h_RT[10]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[2] -= 2 * q; // O
  wdot[5] += q;     // O2
  // d()/d[O]
  dqdci = +k_f * 2.000000 * sc[2] * sc[10];
  J[30] += -2 * dqdci; // dwdot[O]/d[O]
  J[33] += dqdci;      // dwdot[O2]/d[O]
  // d()/d[O2]
  dqdci = -k_r * sc[10];
  J[72] += -2 * dqdci; // dwdot[O]/d[O2]
  J[75] += dqdci;      // dwdot[O2]/d[O2]
  // d()/d[HE]
  dqdci = +k_f * sc[2] * sc[2] - k_r * sc[5];
  J[142] += -2 * dqdci; // dwdot[O]/d[HE]
  J[145] += dqdci;      // dwdot[O2]/d[HE]
  // d()/dT
  J[184] += -2 * dqdT; // dwdot[O]/dT
  J[187] += dqdT;      // dwdot[O2]/dT

  // reaction 11: H + O + M <=> OH + M
  // a third-body and non-pressure-fall-off reaction
  // 3-body correction factor
  alpha = mixture + (2.5 - 1) * sc[1] + (12 - 1) * sc[4] + (0.75 - 1) * sc[9] +
          (0.75 - 1) * sc[10] + (1.9 - 1) * sc[11] + (3.8 - 1) * sc[12];
  // forward
  phi_f = sc[0] * sc[2];
  k_f = 4714000 * exp(-1 * logT);
  dlnkfdT = -1 * invT;
  // reverse
  phi_r = sc[3];
  Kc = refCinv * (kc_fast ? (ge[3] * inv_ge[0] * inv_ge[2])
                          : exp(g_RT[0] + g_RT[2] - g_RT[3]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[0] + h_RT[2]) + (h_RT[3]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
  q = alpha * q_nocor;
  dqdT = alpha * (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
