    J[144] -= dqdci; // dwdot[H2O]/d[HE]
    // d()/d[CO]
    dqdci = (1.9 - 1) * q_nocor;
    J[154] += dqdci; // dwdot[H]/d[CO]
    J[157] += dqdci; // dwdot[OH]/d[CO]
    J[158] -= dqdci; // dwdot[H2O]/d[CO]
    // d()/d[CO2]
    dqdci = (3.8 - 1) * q_nocor;
    J[168] += dqdci; // dwdot[H]/d[CO2]
    J[171] += dqdci; // dwdot[OH]/d[CO2]
