  dqdci = -k_r * sc[3] * sc[4];
  J[0] += dqdci; // dwdot[H]/d[H]
  J[3] += dqdci; // dwdot[OH]/d[H]
  J[4] -= dqdci; // dwdot[H2O]/d[H]
