  J[2] -= dqdci; // dwdot[O]/d[H]
  J[3] += dqdci; // dwdot[OH]/d[H]
  // d()/d[H2]
  dqdci = +k_f * sc[2];
  J[14] += dqdci; // dwdot[H]/d[H2]
  J[15] -= dqdci; // dwdot[H2]/d[H2]
